class Warehouse {
  inventory = new Map();      // productId -> 实际在库数量
  reserved = new Map();       // productId -> 已占用未扣减
  reservations = new Map();   // reservationId -> Reservation

  available(productId) {      // 可售 = 在库 - 已占用
    return (this.inventory.get(productId) ?? 0)
         - (this.reserved.get(productId) ?? 0);
  }
}
