List<AlertListener> getAlertsToFire(String pid, int prev, int next) {
  List<AlertConfig> configs = alertConfigs.get(pid);
  if (configs == null) return List.of();
  List<AlertListener> fired = new ArrayList<>();
  for (AlertConfig c : configs) {
    // only fire on downward crossing, not every low read
    if (prev >= c.threshold() && next < c.threshold())
      fired.add(c.listener());
  }
  return fired;
}
